 Vtx=random.randint(0,3);cache=random.randint(0,8);hit=random.randint(1,4);miss=random.randint(hit,10);dec=[random.randint(0,4) for _ in range(3)];cost=[hit,miss,dec]
 initial=[];routes={}
 for st,l in random.sample(pool,random.randint(0,len(pool))):
