 if any(len(ss)>6 for ss,hh in versions):continue
 # no bursts to simplify
 rawcase={'initial':initial,'transactions':txs,'bursts':[],'cache_pages':cache,'costs':{'hit':hit,'miss':miss,'decode':dec}}
